insert into public.cities(id,name,country,cost_index,popularity,image_url) values
('paris','Paris','France',4,98,'https://images.unsplash.com/photo-1502602898657-3e91760cbb34?auto=format&fit=crop&w=1200&q=80'),('tokyo','Tokyo','Japan',4,97,'https://images.unsplash.com/photo-1540959733332-eab4deabeeaf?auto=format&fit=crop&w=1200&q=80'),('new-york','New York','USA',5,96,'https://images.unsplash.com/photo-1485871981521-5b1fd3805eee?auto=format&fit=crop&w=1200&q=80'),('dubai','Dubai','UAE',5,91,null),('london','London','United Kingdom',5,94,null),('singapore','Singapore','Singapore',4,90,null),('bali','Bali','Indonesia',2,93,null),('barcelona','Barcelona','Spain',3,89,null),('rome','Rome','Italy',3,92,null),('zurich','Zurich','Switzerland',5,82,null) on conflict(id) do update set name=excluded.name,country=excluded.country,cost_index=excluded.cost_index,popularity=excluded.popularity,image_url=excluded.image_url;
insert into public.activities(id,city_id,name,category,cost,duration_minutes,description,image_url) values
('paris-louvre','paris','Louvre Museum','culture',24,180,'Masterpieces and monumental galleries in the heart of Paris.',null),('paris-seine','paris','Seine Dinner Cruise','food',95,150,'Evening dining with illuminated river views.',null),('tokyo-teamlab','tokyo','teamLab Planets','culture',30,120,'Immersive digital art across water and light.',null),('tokyo-tsukiji','tokyo','Tsukiji Food Tour','food',82,180,'Taste sushi and local market specialties.',null),('new-york-broadway','new-york','Broadway Evening','culture',145,165,'A world-class live performance.',null) on conflict(id) do nothing;
insert into public.activities(id,city_id,name,category,cost,duration_minutes,description) select c.id||'-highlights',c.id,c.name||' Highlights Tour','sightseeing',38,180,'A curated introduction to the essential sights of '||c.name from public.cities c on conflict(id) do nothing;
insert into public.activities(id,city_id,name,category,cost,duration_minutes,description) select c.id||'-local-table',c.id,c.name||' Local Table','food',64,120,'A memorable tasting of local dishes and stories in '||c.name from public.cities c on conflict(id) do nothing;
insert into public.activities(id,city_id,name,category,cost,duration_minutes,description) select c.id||'-after-dark',c.id,c.name||' After Dark','nightlife',48,150,'Discover atmospheric venues and evening culture in '||c.name from public.cities c on conflict(id) do nothing;
